/* Brochure library.
   - Documents: View PDF opens in a new tab and Download PDF carries the download
     attribute (same-origin files download; other hosts open instead). A document
     with no file linked yet is marked disabled instead of being a dead link. */
(function () {
  document.querySelectorAll('[data-bz-section="doc-library"] [data-bz-node^="lib-dact"] a').forEach(function (a, i) {
    var href = a.getAttribute('href');
    if (!href || href === '#') {
      a.setAttribute('aria-disabled', 'true');
      a.setAttribute('tabindex', '-1');
      a.addEventListener('click', function (e) { e.preventDefault(); });
      return;
    }
    if (/^download/i.test(a.textContent.trim())) {
      a.setAttribute('download', '');
    } else {
      a.setAttribute('target', '_blank');
      a.setAttribute('rel', 'noopener');
    }
  });
})();
